#!/usr/bin/env node
/**
 * Builds `supabase/apply-all.sql` — one paste-ready script for the Supabase
 * SQL Editor (Dashboard -> SQL Editor -> New query -> Run).
 *
 * It concatenates, in order:
 *   1. supabase/migrations/20260101000000_init_schema.sql
 *   2. supabase/migrations/20260101000100_rls_and_storage.sql
 *   3. supabase/migrations/20260101000200_auth_helpers.sql
 *   4. supabase/migrations/20260101000300_storage_write_policies.sql
 *   5. supabase/migrations/20260101000400_updated_at_triggers.sql
 *   6. supabase/migrations/20260101000500_public_site_stats.sql
 *   7. supabase/migrations/20260101000600_customer_directory.sql
 *   8. supabase/migrations/20260101000900_auto_cancel_stale_bookings.sql
 *   9. supabase/seed.sql
 *  10. supabase/seed-car-images.sql
 *  11. supabase/migrations/20260101000700_auth_users_sync.sql
 *  12. supabase/migrations/20260101000800_auth_user_provisioning.sql
 *  13. supabase/backfill-auth.sql
 *
 * The auth sync triggers are created *after* the seed on purpose: the seed
 * inserts legacy users first, then `backfill-auth.sql` creates their
 * `auth.users` shadows. Creating the triggers before the seed would make the
 * `auth.users` insert-trigger provision a duplicate legacy row.
 *
 * Everything in the bundle is idempotent (`if not exists` / `if exists` /
 * `on conflict do nothing`), so it is safe to run more than once.
 *
 * Usage: node scripts/build-sql-bundle.mjs
 */

import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const PROJECT_ROOT = path.resolve(__dirname, "..");
const SUPABASE_DIR = path.join(PROJECT_ROOT, "supabase");

const PARTS = [
  "migrations/20260101000000_init_schema.sql",
  "migrations/20260101000100_rls_and_storage.sql",
  "migrations/20260101000200_auth_helpers.sql",
  "migrations/20260101000300_storage_write_policies.sql",
  "migrations/20260101000400_updated_at_triggers.sql",
  "migrations/20260101000500_public_site_stats.sql",
  "migrations/20260101000600_customer_directory.sql",
  "migrations/20260101000900_auto_cancel_stale_bookings.sql",
  "migrations/20260101001000_car_amortization.sql",
  "migrations/20260101001100_restore_bookings_foreign_keys.sql",
  "seed.sql",
  "seed-car-images.sql",
  "migrations/20260101000700_auth_users_sync.sql",
  "migrations/20260101000800_auth_user_provisioning.sql",
  "backfill-auth.sql",
];

const header = `-- ============================================================================
-- InstaCar — full database bootstrap (paste into the Supabase SQL Editor)
-- ----------------------------------------------------------------------------
-- Generated by scripts/build-sql-bundle.mjs. Do not edit by hand.
--
-- What this creates
--   * every table / enum / index of the legacy MySQL dump
--     (users, branches, cars, car_schedules, bookings, booking_payments,
--      booking_photos, booking_remarks, reviews, contact_messages, expenses,
--      site_content, operator_remittances, operator_remittance_photos,
--      staff_fee_remittances, staff_fee_remittance_photos)
--   * the RLS policies and helper functions used by the PHP session logic
--   * the 5 storage buckets + their policies
--       car-images (public)            <- images/cars/*
--       booking-uploads (private)      <- images/ids/<folder>/*
--       booking-photos (private)       <- images/customers/*
--       remittance-photos (private)    <- images/remittances/*
--       site-assets (public)           <- images/qr_code_payment.png
--   * the seed rows from the legacy dump (57 rows, legacy primary keys)
--   * the public.users <-> auth.users link:
--       - BEFORE trigger creates the Supabase Auth shadow row
--       - AFTER triggers keep both tables in sync (password, e-mail, profile)
--       - a self-service sign-up is provisioned into public.users
--       - backfill-auth.sql creates the Auth account of every seeded user
--
-- Every seeded account can sign in with its original password because GoTrue
-- verifies the legacy PHP bcrypt hashes natively.
--
-- It is idempotent: running it twice is harmless.
--
-- After this, upload the images with:
--   node scripts/upload-images.mjs            (cars only)
--   node scripts/upload-images.mjs --scope=all
-- ============================================================================

`;

const chunks = [header];

for (const part of PARTS) {
  const file = path.join(SUPABASE_DIR, part);
  if (!fs.existsSync(file)) {
    console.error(`Missing part: ${part}`);
    process.exit(1);
  }
  const body = fs.readFileSync(file, "utf8");
  chunks.push(
    `\n-- ${"-".repeat(74)}\n-- ${part}\n-- ${"-".repeat(74)}\n\n${body}\n`,
  );
}

const output = path.join(SUPABASE_DIR, "apply-all.sql");
fs.writeFileSync(output, chunks.join(""), "utf8");

const bytes = fs.statSync(output).size;
console.log(`Wrote ${output} (${(bytes / 1024).toFixed(1)} KB, ${PARTS.length} parts)`);
